package com.example.campsitelotterysystem.controller

import com.example.campsitelotterysystem.db.CampsiteDB
import com.example.campsitelotterysystem.model.Campsite


import com.example.campsitelotterysystem.model.Filter
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.Calendar
import java.util.Date


/** Unit tests for CampsiteController.filterCampsites. It is a pure function, so no Firebase is needed.
* This Test was generated by AI - Claude 2026-11-05 - "write test cases to validate errors"
*/
class CampsiteControllerTest {

    /** A pretend database. filterCampsites never calls it, but the controller needs one. */
    private class FakeCampsiteDB : CampsiteDB {
        override fun addCampsite(campsite: Campsite, onSuccess: (String) -> Unit, onFailure: (Exception) -> Unit) {}
        override fun removeCampsite(campsite: Campsite, onSuccess: (String) -> Unit, onFailure: (Exception) -> Unit) {}
        override fun updateCampsite(campsite: Campsite, onSuccess: () -> Unit, onFailure: (Exception) -> Unit) {}
        override fun getCampsite(id: String, onSuccess: (Campsite?) -> Unit, onFailure: (Exception) -> Unit) {}
        override fun getCampsitesByOwner(ownerId: String, onSuccess: (List<Campsite>) -> Unit, onFailure: (Exception) -> Unit) {}
        override fun getAllCampsites(onSuccess: (List<Campsite>) -> Unit, onFailure: (Exception) -> Unit) {}
        override fun removeAllCampsitesByOwner(ownerId: String, onSuccess: () -> Unit, onFailure: (Exception) -> Unit) {}
    }

    private val controller = CampsiteController(FakeCampsiteDB())

    /** Builds a Date in the device's time zone, the same zone the filter uses. */
    private fun date(year: Int, month: Int, day: Int, hour: Int = 12): Date =
        Calendar.getInstance().apply {
            clear()
            set(year, month - 1, day, hour, 0, 0)
        }.time

    private val banff = Campsite(
        name = "Lake Louise Pine Camp",
        location = "Banff, AB",
        maximumOccupancy = 4,
        availableDates = listOf(date(2026, 12, 9), date(2026, 12, 10))
    )
    private val jasper = Campsite(
        name = "Jasper Fire Camp",
        location = "Jasper, AB",
        maximumOccupancy = 2,
        availableDates = listOf(date(2026, 12, 20))
    )
    private val noDates = Campsite(
        name = "Quiet Camp",
        location = "Canmore, AB",
        maximumOccupancy = 6
    )
    private val all = listOf(banff, jasper, noDates)

    private fun names(result: List<Campsite>) = result.map { it.name }

    @Test
    fun emptyFilterReturnsEveryCampsite() {
        val result = controller.filterCampsites(all, Filter())
        assertEquals(all, result)
    }

    @Test
    fun locationFilterMatchesText() {
        val result = controller.filterCampsites(all, Filter(location = "Banff"))
        assertEquals(listOf("Lake Louise Pine Camp"), names(result))
    }

    @Test
    fun locationFilterIgnoresCaseAndSpaces() {
        val result = controller.filterCampsites(all, Filter(location = "  jasper "))
        assertEquals(listOf("Jasper Fire Camp"), names(result))
    }

    @Test
    fun locationFilterWithNoMatchReturnsNothing() {
        val result = controller.filterCampsites(all, Filter(location = "Calgary"))
        assertTrue(result.isEmpty())
    }

    @Test
    fun guestFilterKeepsCampsitesThatFitEveryone() {
        val result = controller.filterCampsites(all, Filter(numberOfGuests = 4))
        assertEquals(listOf("Lake Louise Pine Camp", "Quiet Camp"), names(result))
    }

    @Test
    fun guestFilterAllowsExactCapacity() {
        val result = controller.filterCampsites(all, Filter(numberOfGuests = 2))
        assertEquals(3, result.size)
    }

    @Test
    fun zeroGuestsMeansAny() {
        val result = controller.filterCampsites(all, Filter(numberOfGuests = 0))
        assertEquals(all, result)
    }

    @Test
    fun dateRangeKeepsCampsitesWithADateInside() {
        val range = Pair(date(2026, 12, 8), date(2026, 12, 12))
        val result = controller.filterCampsites(all, Filter(dateRange = range))
        assertEquals(listOf("Lake Louise Pine Camp"), names(result))
    }

    @Test
    fun dateRangeIncludesTheEndDay() {
        // Jasper is only available on Dec 20, which is the last day of the range.
        val range = Pair(date(2026, 12, 18), date(2026, 12, 20, hour = 0))
        val result = controller.filterCampsites(all, Filter(dateRange = range))
        assertEquals(listOf("Jasper Fire Camp"), names(result))
    }

    @Test
    fun dateRangeIncludesTheStartDay() {
        val range = Pair(date(2026, 12, 9, hour = 0), date(2026, 12, 9, hour = 0))
        val result = controller.filterCampsites(all, Filter(dateRange = range))
        assertEquals(listOf("Lake Louise Pine Camp"), names(result))
    }

    @Test
    fun dateRangeExcludesDatesAfterTheEndDay() {
        val range = Pair(date(2026, 12, 18), date(2026, 12, 19))
        val result = controller.filterCampsites(all, Filter(dateRange = range))
        assertTrue(result.isEmpty())
    }

    @Test
    fun campsiteWithNoDatesIsHiddenWhenADateRangeIsApplied() {
        val range = Pair(date(2026, 12, 1), date(2026, 12, 31))
        val result = controller.filterCampsites(listOf(noDates), Filter(dateRange = range))
        assertTrue(result.isEmpty())
    }

    @Test
    fun filtersCombineWithAnd() {
        val range = Pair(date(2026, 12, 8), date(2026, 12, 12))
        val result = controller.filterCampsites(
            all,
            Filter(location = "AB", dateRange = range, numberOfGuests = 4)
        )
        assertEquals(listOf("Lake Louise Pine Camp"), names(result))
    }

    @Test
    fun combinedFiltersCanRuleOutEverything() {
        val result = controller.filterCampsites(
            all,
            Filter(location = "Jasper", numberOfGuests = 5)
        )
        assertTrue(result.isEmpty())

    }
}